def icon(name: str, size: int = 20, cls: str = "", fill: bool = False) -> str:
    """Inline SVG; colour follows `currentColor`. `fill` picks the filled variant when there is one."""
    d = ICON_PATHS.get(name + "-fill") if fill else None
    d = d or ICON_PATHS[name]
    c = f"i {cls}" if cls else "i"
    return (f'<svg class="{c}" viewBox="0 -960 960 960" width="{size}" height="{size}" fill="currentColor" '
            f'aria-hidden="true" focusable="false"><path d="{d}"/></svg>')
